```typescript
type Grouped<T, K extends keyof T> = Record<string, T[]>;

function groupBy<T, K extends keyof T>(array: T[], key: K): Grouped<T, K> {
  const map = new Map<string, T[]>();

  for (const item of array) {
    const keyValue = item[key] as unknown as string;

    if (!map.has(keyValue)) {
      map.set(keyValue, []);
    }

    map.get(keyValue)?.push(item);
  }

  return Object.fromEntries(map) as Grouped<T, K>;
}
```

